import {entityIcon,entityIconPicker} from './entity-icons.js';
import {correlationOverlayHTML} from './correlation-overlay.js';
import {period,shiftPeriod,addDays,today,dateOf} from './model.js';
import {durationLabel,sleepMinutes} from './wellness.js';
import {analyticsRows,analyticsSummary,metricOptions,correlation} from './analytics.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=1)=>n===null||n===undefined?'—':Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d});
const date=(s,opts={day:'numeric',month:'short'})=>dateOf(s).toLocaleDateString('ru-RU',{...opts,timeZone:'UTC'});
const value=(state,day,id)=>state.habitEntries[day]?.[id];
function heading(eyebrow,title,subtitle,actions=''){return `<div class="well-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${actions}</div>`;}
function weekStrip(state,day,kind){const start=period('week',day).start;return `<div class="well-week" aria-label="Дни недели">${Array.from({length:7},(_,i)=>{const d=addDays(start,i),entries=Object.values(state.habitEntries[d]||{}),log=state.dayLogs[d],has=kind==='habits'?entries.length:log&&(sleepMinutes(d,log)!==null||log.wellbeing!==null),met=entries.filter(e=>e.value>=e.target).length;return `<button class="well-week-day ${d===day?'selected':''} ${d===today()?'is-today':''} ${has?'has-entry':''}" data-action="well-day" data-date="${d}" aria-label="${date(d,{day:'numeric',month:'long'})}${d===today()?', сегодня':''}${has?', есть запись':''}" ${d===today()?'aria-current="date"':''} aria-pressed="${d===day}"><span>${date(d,{weekday:'short'})}</span><strong>${date(d,{day:'numeric'})}</strong><small>${kind==='habits'?(entries.length?met+' / '+entries.length:'·'):(log?.wellbeing!=null?log.wellbeing+' / 10':has?'◷':'·')}</small></button>`;}).join('')}</div>`;}
function habitViewToggle(view){return `<div class="habit-view-toggle" role="group" aria-label="Вид привычек"><button data-action="habit-view" data-view="cards" aria-pressed="${view==='cards'}" title="Карточки">▦ <span>Карточки</span></button><button data-action="habit-view" data-view="list" aria-pressed="${view==='list'}" title="Список">☷ <span>Список</span></button></div>`;}
function habitItemsHTML(state,day,habits,view='cards',archived=false){
  return `<div class="habit-grid ${view==='list'?'habit-list':''}">${habits.map(h=>{
    const e=value(state,day,h.id),amount=e?.value||0,target=e?.target??h.target,unit=e?.unit??h.unit,percent=Math.min(100,amount/target*100),done=amount>=target,available=day>=h.createdOn,disabled=!available?'disabled':'';
    return `<article class="habit-card ${!archived&&done?'goal-met':''} ${archived?'archived-habit':''}"><div class="habit-card-head"><span class="habit-symbol" aria-hidden="true">${entityIcon(h,'habit')}</span><div><h2>${esc(h.name)}</h2><span class="habit-goal-label">Цель ${num(target)} ${esc(unit)} в день</span></div><button class="entity-edit" data-action="edit-habit" data-id="${esc(h.id)}" aria-label="Изменить привычку ${esc(h.name)}">✎</button></div>${archived?`<p class="habit-archive-meta">Шаг ${num(h.step)} ${esc(h.unit)} · В архиве с ${date(h.archivedOn)}</p><button class="secondary-button habit-add" data-action="restore-habit" data-id="${esc(h.id)}">Вернуть привычку</button>`:`<button class="habit-value" data-action="habit-entry" data-id="${esc(h.id)}" aria-label="Изменить результат ${esc(h.name)} за день" ${disabled}><strong>${num(amount)}</strong><span>/ ${num(target)} ${esc(unit)}</span></button><div class="habit-progress" role="progressbar" aria-label="Достижение цели ${esc(h.name)}" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(amount,target)}"><i style="width:${percent}%"></i></div><div class="habit-status"><span>${!available?'Начало '+date(h.createdOn):done?'✓ Дневная цель достигнута':e?num(amount/target*100,0)+'% дневной цели':'Пока нет записи'}</span><button class="text-button" data-action="habit-entry" data-id="${esc(h.id)}" ${disabled}>Исправить</button></div><div class="habit-buttons"><button class="secondary-button habit-subtract" data-action="habit-minus" data-id="${esc(h.id)}" aria-label="Вычесть ${num(h.step)}: ${esc(h.name)}" ${amount===0||!available?'disabled':''}>−${num(h.step)}</button><button class="primary-button habit-add" data-action="habit-plus" data-id="${esc(h.id)}" ${disabled}>+${num(h.step)} <span>${esc(h.unit)}</span></button></div>`}</article>`;
  }).join('')}</div>`;
}
function habitsEmpty(){return `<div class="well-empty panel"><span class="empty-symbol">◎</span><h2>Добавьте первую привычку</h2><p>Задайте дневную цель и шаг счётчика.</p><div class="habit-presets"><button class="secondary-button" data-action="habit-preset" data-preset="water">Вода · +250 мл</button><button class="secondary-button" data-action="habit-preset" data-preset="reading">Чтение · +10 мин</button><button class="primary-button" data-action="new-habit">Своя привычка</button></div></div>`;}
export function habitsHTML(state,day,{view='cards',archiveOpen=false}={}){
  const habits=state.habits.filter(h=>!h.archivedOn),archived=state.habits.filter(h=>h.archivedOn);
  return heading('МАЛЕНЬКИЕ ДЕЙСТВИЯ · КАЖДЫЙ ДЕНЬ','Привычки','',`<button class="primary-button" data-action="new-habit">+ Новая привычка</button>`)+`<div class="habit-section-toolbar habit-layout-toolbar">${habitViewToggle(view)}</div><div id="habit-active-items">${habits.length?habitItemsHTML(state,day,habits,view):habitsEmpty()}</div><details class="habit-archive flow-section" id="habit-archive" ${archiveOpen?'open':''}><summary>Архив привычек <span class="count">${archived.length}</span></summary><div class="habit-archive-content flow-section-body">${archived.length?habitItemsHTML(state,day,archived,view,true):'<p class="well-muted">Архив пуст.</p>'}</div></details>`;
}
export function plannerHabitsHTML(state,day){
  const habits=state.habits.filter(h=>h.createdOn<=day&&(!h.archivedOn||h.archivedOn>day));
  return `<h2 class="daily-habits-title">Привычки дня</h2>${habits.length?`<div class="daily-habit-list">${habits.map(h=>{
    const e=value(state,day,h.id),amount=e?.value||0,target=e?.target??h.target,unit=e?.unit??h.unit,done=amount>=target;
    return `<article class="daily-habit ${done?'goal-met':''}"><div class="daily-habit-name"><h3>${esc(h.name)}</h3><span>Цель ${num(target)} ${esc(unit)}</span></div><button class="daily-habit-value" data-action="habit-entry" data-id="${esc(h.id)}" aria-label="Изменить результат ${esc(h.name)} за день"><strong>${num(amount)}</strong><span>/ ${num(target)} ${esc(unit)}</span></button><div class="daily-habit-progress" role="progressbar" aria-label="Достижение цели ${esc(h.name)}" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(amount,target)}"><i style="width:${Math.min(100,amount/target*100)}%"></i></div><div class="daily-habit-actions"><button class="secondary-button" data-action="habit-minus" data-id="${esc(h.id)}" aria-label="Вычесть ${num(h.step)}: ${esc(h.name)}" ${amount===0?'disabled':''}>−${num(h.step)}</button><button class="primary-button" data-action="habit-plus" data-id="${esc(h.id)}">+${num(h.step)} ${esc(h.unit)}</button></div></article>`;
  }).join('')}</div>`:'<p class="daily-habits-empty">Пока нет привычек.</p>'}`;
}
export function habitForm(h={},preset=''){
  if(preset==='water')h={name:'Вода',unit:'мл',step:250,target:2000,icon:'water'};if(preset==='reading')h={name:'Чтение',unit:'мин',step:10,target:30,icon:'book'};
  return `<h2>${h.id?'Изменить привычку':'Новая привычка'}</h2><p class="modal-description">Дневная цель и один шаг, который удобно прибавлять кнопкой.</p><form id="habit-form" data-id="${esc(h.id||'')}"><label class="form-label" for="habit-name">Название</label><input class="field" id="habit-name" required maxlength="100" placeholder="Например, Вода" value="${esc(h.name||'')}">${entityIconPicker(h,'habit')}<div class="form-grid"><div><label class="form-label" for="habit-target">Дневная цель</label><input class="field" type="number" id="habit-target" min="0.001" max="1000000000" step="0.001" required value="${h.target??2000}"></div><div><label class="form-label" for="habit-step">Шаг кнопки +</label><input class="field" type="number" id="habit-step" min="0.001" max="1000000000" step="0.001" required value="${h.step??250}"></div></div><label class="form-label" for="habit-unit">Единица измерения</label><input class="field" id="habit-unit" maxlength="30" placeholder="мл, шагов, минут, раз…" value="${esc(h.unit??'мл')}">${h.id?'<p class="form-note">Новая цель и единица применяются к дням без записи. У записанных дней остаётся прежняя цель. Шаг кнопки меняется сразу.</p>':''}<div class="error-text" id="habit-error" role="alert"></div>${h.id?`<div class="entity-lifecycle-actions"><button type="button" class="secondary-button" data-action="${h.archivedOn?'restore-habit':'archive-habit'}" data-id="${esc(h.id)}">${h.archivedOn?'Вернуть из архива':'В архив'}</button><button type="button" class="danger-button" data-action="delete-habit" data-id="${esc(h.id)}">Удалить привычку</button></div>`:''}<div class="modal-actions"><button type="button" class="secondary-button" data-action="close-modal">Отмена</button><button class="primary-button" type="submit">Сохранить привычку</button></div></form>`;
}
export function habitDeleteConfirmation(h,entryCount){return `<h2>Удалить привычку?</h2><p class="modal-description">${esc(h.name)}</p><div class="hint-box">Привычка и все её записи (${entryCount}) будут удалены без возможности восстановления. Она исчезнет из «Сегодня», архива и аналитики.</div><div class="modal-actions"><button type="button" class="secondary-button" data-action="close-modal">Отмена</button><button type="button" class="danger-button" data-action="confirm-delete-habit" data-id="${esc(h.id)}">Удалить привычку и записи</button></div>`;}
export function habitEntryForm(state,id,day){const h=state.habits.find(h=>h.id===id),e=value(state,day,id);return `<h2>${esc(h.name)} · результат дня</h2><p class="modal-description">${date(day,{day:'numeric',month:'long',year:'numeric'})} · ${esc(e?.unit??h.unit)}</p><form id="habit-entry-form" data-id="${esc(id)}"><label class="form-label" for="habit-amount">Точное значение</label><input class="field" id="habit-amount" type="number" min="0" max="1000000000" step="0.001" required value="${e?.value??0}"><div class="form-note">Ноль — отмеченный день без результата. «Убрать запись» вернёт отсутствие данных.</div><div class="error-text" id="habit-error" role="alert"></div><div class="modal-actions">${e?`<button type="button" class="danger-button" data-action="clear-habit-entry" data-id="${esc(id)}">Убрать запись</button>`:''}<button class="primary-button" type="submit">Сохранить результат</button></div></form>`;}
export const diaryWeekHTML=(state,day)=>weekStrip(state,day,'diary');
export function adjacentPeriodsHTML(type,anchor){
  const selected=period(type,anchor),actual=period(type,today()),nouns={week:['неделя','недели'],quarter:['квартал','кварталы'],year:['год','годы']},noun=nouns[type]||nouns.year;
  return `<div class="adjacent-periods" role="group" aria-label="Соседние ${noun[1]}">${[-1,0,1].map(offset=>{
    const target=period(type,shiftPeriod(type,anchor,offset)),name=type==='week'?target.label.split(' · ')[0]:type==='quarter'?target.label:target.start.slice(0,4),caption=offset===0&&target.key===actual.key?(type==='week'?'Текущая':'Текущий'):offset<0?(type==='week'?'Прошлая':'Предыдущий'):offset>0?(type==='week'?'Следующая':'Следующий'):(type==='week'?'Выбранная':'Выбранный'),isCurrent=target.key===actual.key;
    const detail=type==='week'?date(target.start)+' — '+date(target.end):type==='quarter'?date(target.start,{month:'short'})+' — '+date(target.end,{month:'short'})+' '+target.start.slice(0,4):'';
    return `<button class="period-choice ${target.key===selected.key?'selected':''} ${isCurrent?'is-current-period':''}" data-action="select-period" data-date="${target.start}" aria-label="${caption} ${noun[0]}: ${esc(name)} ${esc(detail)}${isCurrent?', текущая дата в этом периоде':''}" aria-pressed="${target.key===selected.key}" ${isCurrent?'aria-current="date"':''}><span class="period-choice-caption">${caption} ${noun[0]}</span><strong>${esc(name)}</strong>${detail?`<small>${esc(detail)}</small>`:''}</button>`;
  }).join('')}</div>`;
}
export function diaryFormHTML(state,day){
  const log=state.dayLogs[day]||{},minutes=sleepMinutes(day,log),bed=log.bedDate&&log.bedTime?log.bedDate+'T'+log.bedTime:'';
  return `<form id="diary-form" class="compact-diary"><div class="diary-grid"><section class="diary-card wellbeing-card"><div class="compact-review-heading"><h3>Как прошёл день?</h3><button class="text-button" type="button" data-action="clear-wellbeing">Убрать оценку</button></div><fieldset class="wellbeing-fieldset"><legend class="visually-hidden">Самочувствие от 1 до 10</legend><div class="wellbeing-scale">${Array.from({length:10},(_,i)=>`<label><input type="radio" name="wellbeing" value="${i+1}" ${log.wellbeing===i+1?'checked':''}><span>${i+1}</span></label>`).join('')}</div></fieldset></section><section class="diary-card compact-sleep"><div class="compact-review-heading"><h3>Сон к утру ${date(day)}</h3><strong id="sleep-duration">${durationLabel(minutes)}</strong></div><div class="sleep-fields"><div><label class="form-label" for="sleep-bed-datetime">Когда лёг</label><input class="field" type="datetime-local" id="sleep-bed-datetime" step="60" value="${esc(bed)}" max="${day}T23:59"></div><div><label class="form-label" for="sleep-wake-time">Во сколько встал</label><input class="field" type="time" id="sleep-wake-time" value="${esc(log.wakeTime||'')}"></div></div></section></div><div class="error-text" id="diary-error" role="alert"></div></form>`;
}
export function plannerDiaryHTML(state,day){return `<section id="day-review" class="planner-diary" aria-label="Дневник выбранного дня">${diaryFormHTML(state,day)}</section>`;}
function metricSelect(id,metrics,current){return `<select class="field" id="${id}">${metrics.map(m=>`<option value="${esc(m.id)}" ${m.id===current?'selected':''}>${esc(m.label)}${m.unit?' · '+esc(m.unit):''}</option>`).join('')}</select>`;}
function scatterChart(pairs,mx,my){
  if(!pairs.length)return `<div class="chart-empty"><span>⠿</span><h3>Записи ещё не совпали по датам</h3><p>Для точки нужны обе метрики за один день или неделю. Пропуски не заменяются нулями.</p></div>`;
  const W=680,H=300,L=65,R=25,T=20,B=60,w=W-L-R,h=H-T-B,xmax=mx.max||Math.max(1,...pairs.map(p=>p.x))*1.12,ymax=my.max||Math.max(1,...pairs.map(p=>p.y))*1.12,x=v=>L+w*v/xmax,y=v=>T+h*(1-v/ymax);let grid='';
  for(let i=0;i<=4;i++){grid+=`<line x1="${L}" x2="${W-R}" y1="${y(ymax*i/4)}" y2="${y(ymax*i/4)}" class="chart-grid"/><text x="${L-10}" y="${y(ymax*i/4)+4}" text-anchor="end">${num(ymax*i/4)}</text><text x="${x(xmax*i/4)}" y="${H-B+22}" text-anchor="middle">${num(xmax*i/4)}</text>`;}
  return `<svg class="data-chart scatter-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Связь: ${esc(mx.label)} и ${esc(my.label)}. ${pairs.length} точек"><title>${esc(mx.label)} и ${esc(my.label)}</title>${grid}${pairs.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="6" class="scatter-dot"><title>${date(p.date)}: ${num(p.x)} ${esc(mx.unit)} / ${num(p.y)} ${esc(my.unit)}</title></circle>`).join('')}<text class="axis-label" x="${L+w/2}" y="${H-8}" text-anchor="middle">${esc(mx.label)} (${esc(mx.unit)})</text><text class="axis-label" transform="translate(15 ${T+h/2}) rotate(-90)" text-anchor="middle">${esc(my.label)} (${esc(my.unit)})</text></svg>`;
}
export function analyticsHTML(state,ctx){
  const overlay=ctx.chart!=='scatter',metrics=metricOptions(state,ctx.grain),mx=metrics.find(m=>m.id===ctx.x)||metrics[0],my=metrics.find(m=>m.id===ctx.y)||metrics[2],data=analyticsRows(state,ctx),summary=analyticsSummary(state,ctx),pairs=data.rows.filter(r=>Number.isFinite(r[mx.id])&&Number.isFinite(r[my.id])).map(r=>({date:r.date,x:r[mx.id],y:r[my.id]})),corr=correlation(pairs),r=corr.r,strength=r===null?'':Math.abs(r)<.2?'Почти нет линейной связи':Math.abs(r)<.5?'Слабая линейная связь':Math.abs(r)<.7?'Умеренная линейная связь':'Сильная линейная связь';
  return heading('НАБЛЮДАТЬ, А НЕ УГАДЫВАТЬ','Аналитика','Как сон, самочувствие и ежедневные действия связаны с выполнением плана.')+`<div class="analytics-controls"><label>Период<select class="field" id="analytics-span">${[[1,'Неделя'],[4,'4 недели'],[12,'12 недель']].map(([v,t])=>`<option value="${v}" ${ctx.span===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Неделя, включающая<input class="field" type="date" id="analytics-date" value="${ctx.anchor}"></label><label>Группировка<select class="field" id="analytics-grain"><option value="day" ${ctx.grain==='day'?'selected':''}>По дням</option><option value="week" ${ctx.grain==='week'?'selected':''}>По неделям</option></select></label><span class="analytics-range">${date(data.start)} — ${date(data.end,{day:'numeric',month:'short',year:'numeric'})}</span></div><section class="analytics-metrics"><article><span>Сон в среднем</span><strong>${summary.sleep===null?'—':num(summary.sleep,2)} <small>ч / ночь</small></strong><p>Ночей с записью: ${summary.sleepCount}</p></article><article><span>Самочувствие в среднем</span><strong>${num(summary.wellbeing)} <small>/ 10</small></strong><p>Дней с оценкой: ${summary.wellbeingCount}</p></article><article><span>Выполнено из плана</span><strong>${summary.completed} <small>/ ${summary.planned} задач</small></strong><p>${summary.productivity===null?'Нет зафиксированных недельных планов':num(summary.productivity,0)+'% запланированного'}</p></article><article><span>Недельных планов</span><strong>${data.fixedWeeks} <small>/ ${ctx.span}</small></strong><p>Учитываются только зафиксированные</p></article></section><section class="panel chart-card correlation-card"><div class="chart-card-heading"><div><h2>Связь между метриками</h2><p>${overlay?'Две линии на общей временной шкале. '+(ctx.grain==='week'?'Одна точка — неделя.':'Одна точка — день.'):'Одна точка — пара наблюдений за один и тот же день или неделю.'}</p></div><div class="correlation-heading-actions">${correlationViewToggle(overlay)}<span class="badge">Пар ${ctx.grain==='week'?'недель':'дней'}: ${pairs.length}</span></div></div><div class="correlation-selects"><label>${overlay?'Первая линия':'По горизонтали · X'}${metricSelect('analytics-x',metrics,mx.id)}</label><span aria-hidden="true">↔</span><label>${overlay?'Вторая линия':'По вертикали · Y'}${metricSelect('analytics-y',metrics,my.id)}</label></div><div class="correlation-body"><div>${overlay?correlationOverlayHTML(data.rows,mx,my):scatterChart(pairs,mx,my)}</div><aside class="correlation-insight"><span class="eyebrow">КОРРЕЛЯЦИЯ ПИРСОНА</span><strong>${r===null?'—':num(r,2)}</strong><h3>${r===null?'Пока недостаточно данных':strength}</h3><p>${r===null?corr.reason:(r>0?'При росте одной метрики в этих записях чаще росла и другая.':r<0?'При росте одной метрики другая чаще снижалась.':'В этих записях линейная связь не обнаружена.')}</p><p class="correlation-caution">${r!==null&&corr.n<10?'Мало наблюдений: результат может заметно меняться. ':''}Связь не доказывает причину.</p></aside></div></section><details class="analytics-method flow-section" data-collapse-key="analytics:method"><summary>Как считаются показатели</summary><div class="flow-section-body"><p><b>Сон:</b> разница между датой и временем отхода ко сну и пробуждения. Ночь привязана к утру. Среднее — только по заполненным ночам, без подстановки нулей.</p><p><b>Неделя:</b> выполненные в пределах недели задачи / все задачи её зафиксированного плана. Отменённые и отсутствующие задачи остаются в знаменателе. Архивные выполнения сохраняются. Кварталы, дни и годы не добавляются, чтобы не считать одну задачу повторно.</p><p><b>День:</b> берётся зафиксированный план дня; выполнением считается завершение в этот день. Если дневной план ещё не зафиксирован, используются задачи недельного снимка со сроком на этот день и завершение к сроку. Задачи без такого срока участвуют только в недельном проценте. «Выполнено из недельного плана» по дням — число завершений в этот день, независимо от срока.</p><p><b>Привычки:</b> результат за день или средний результат по отмеченным дням недели. У записанных дней сохраняются их цели и единицы. После смены единицы измерения используйте новую привычку для сопоставимой аналитики.</p><p><b>Наложение линий:</b> для каждой метрики 0% — минимум выбранного периода, 100% — максимум. Это относительная шкала для сравнения изменений. Постоянное значение рисуется на 50%; пропуски не заполняются. Корреляция рассчитывается по исходным значениям совпавших дат.</p><p>Текущие день и неделя ещё могут измениться. Будущие дни исключены. Для корреляции нужны минимум 3 совпавших наблюдения с меняющимися значениями; на коротком периоде вывод ненадёжен.</p></div></details><details class="analytics-data flow-section" data-collapse-key="analytics:data"><summary>Данные за период · строк: ${data.rows.length}</summary><div class="flow-section-body"><div class="task-table-wrap"><table class="analytics-table"><thead><tr><th>Период</th><th>Сон, ч</th><th>Оценка / 10</th><th>${ctx.grain==='week'?'Выполнено / план':'В срок / план дня'}</th><th>План, %</th><th>${esc(mx.label)} (${esc(mx.unit)})</th><th>${esc(my.label)} (${esc(my.unit)})</th></tr></thead><tbody>${data.rows.length?data.rows.map(row=>`<tr><td>${date(row.date)}${ctx.grain==='week'?' — '+date(row.end):''}${row.partial?' · идёт':''}</td><td>${num(row.sleep,2)} <small>(${row.sleepCount} ноч.)</small></td><td>${num(row.wellbeing)} <small>(${row.wellbeingCount} дн.)</small></td><td>${row.planned?(row.completed+' / '+row.planned):'—'}</td><td>${num(row.productivity,0)}</td><td>${num(row[mx.id])}</td><td>${num(row[my.id])}</td></tr>`).join(''):'<tr><td colspan="7">За этот период пока нет данных.</td></tr>'}</tbody></table></div></div></details><div class="well-footnote">${ctx.demo?'Вы смотрите смоделированные записи. Они не добавляются в ваши планы, дневник или резервную копию.':'Записи хранятся вместе с задачами и планами в этом браузере. JSON-копия включает привычки и дневник.'}</div>`;
}



function correlationViewToggle(overlay){return `<div class="correlation-view-toggle" role="group" aria-label="Вид связи между метриками"><button data-action="correlation-view" data-chart="overlay" aria-pressed="${overlay}">Динамика</button><button data-action="correlation-view" data-chart="scatter" aria-pressed="${!overlay}">Точки</button></div>`;}
